CREATE OR REPLACE FUNCTION rakeezx.apply_n58_empty_foundation(p_repair_id text, p_plan jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS E' DECLARE __n88_entry_lock_1031_8c4d text := pg_catalog.pg_advisory_xact_lock(1312307256,88)::text; BEGIN\n\ndeclare v_owner uuid:=auth.uid(); v_prior rakeezx.n58_foundation_repair_receipts%rowtype;\n v_fresh jsonb; v_expected jsonb; v_result jsonb; v_results jsonb:=''[]''; v_year jsonb; v_index integer; v_term jsonb; v_preset text;\nbegin\n if v_owner is null then raise exception using errcode=''42501'',message=''Authentication required''; end if;\n if p_repair_id is null or p_repair_id !~ ''^[a-f0-9-]{36}$'' or jsonb_typeof(p_plan) is distinct from ''object''\n   or octet_length(p_plan::text)>32768 or p_plan->>''ownerId'' is distinct from v_owner::text then raise exception ''N58_REPAIR_INVALID_PLAN''; end if;\n perform rakeezx.lock_student_lifecycle(v_owner);\n select * into v_prior from rakeezx.n58_foundation_repair_receipts where owner_id=v_owner and repair_id=p_repair_id;\n if found then\n  if v_prior.plan is distinct from p_plan then raise exception ''N58_REPAIR_ID_REUSED''; end if;\n  return v_prior.result; -- before rechecking later legitimate school additions\n end if;\n v_fresh:=rakeezx.review_n58_empty_foundation(p_plan->''request'');\n if v_fresh is distinct from p_plan then raise exception ''N58_REPAIR_STALE_PLAN''; end if;\n v_preset:=p_plan->''request''->>''presetId'';v_expected:=rakeezx.n58_repair_expected(v_preset);\n if jsonb_array_length(p_plan->''snapshot''->''years'')=0 then\n  v_result:=rakeezx.apply_sync_v2_mutation(''years'',''y:1448-1449'',p_repair_id||'':year'',p_repair_id,0,v_expected->''year'',''create'',null);\n  if v_result->>''outcome''<>''applied'' then raise exception ''N58_REPAIR_YEAR_NOT_APPLIED''; end if;\n  v_results:=v_results||jsonb_build_array(v_result);\n end if;\n for v_index in 1..2 loop\n  if not exists(select 1 from rakeezx.terms where owner_id=v_owner and id=''tm:y:1448-1449:''||v_index) then\n   v_result:=rakeezx.apply_sync_v2_mutation(''terms'',''tm:y:1448-1449:''||v_index,p_repair_id||'':term''||v_index,p_repair_id,0,v_expected->''terms''->(v_index-1),''create'',null);\n   if v_result->>''outcome''<>''applied'' then raise exception ''N58_REPAIR_TERM_NOT_APPLIED''; end if;\n   v_results:=v_results||jsonb_build_array(v_result);\n  end if;\n end loop;\n select to_jsonb(y) into v_year from rakeezx.years y where owner_id=v_owner and id=''y:1448-1449'';\n if v_year->>''calendar_preset_id'' is distinct from v_preset then\n  v_result:=rakeezx.apply_sync_v2_mutation(''years'',''y:1448-1449'',p_repair_id||'':select'',p_repair_id,(v_year->>''revision'')::bigint,jsonb_build_object(''calendar_preset_id'',v_preset),''patch'',null);\n  if v_result->>''outcome''<>''applied'' then raise exception ''N58_REPAIR_SELECTION_NOT_APPLIED''; end if;\n  v_results:=v_results||jsonb_build_array(v_result);\n end if;\n v_result:=jsonb_build_object(''protocol'',''N58_EMPTY_V1'',''ownerId'',v_owner,''repairId'',p_repair_id,\n  ''planDigest'',encode(sha256(convert_to(p_plan::text,''UTF8'')),''hex''),\n  ''canonical'',rakeezx.n58_repair_snapshot(v_owner,v_preset),''mutationReceipts'',v_results);\n insert into rakeezx.n58_foundation_repair_receipts(owner_id,repair_id,plan,result) values(v_owner,p_repair_id,p_plan,v_result);\n return v_result;\nend ;\nEND; ';
CREATE OR REPLACE FUNCTION rakeezx.apply_reviewed_grade_import(p_mutation_id text, p_device_id text, p_batch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS E' DECLARE __n88_entry_lock_1031_8c4d text := pg_catalog.pg_advisory_xact_lock(1312307256,88)::text; BEGIN\n\ndeclare\n  v_owner uuid:=auth.uid(); v_saved rakeezx.score_domain_receipts%rowtype;\n  v_envelope jsonb; v_result jsonb; v_teaching rakeezx.teachings%rowtype;\n  v_item rakeezx.items%rowtype; v_score rakeezx.scores%rowtype; v_cell jsonb; v_new jsonb;\n  v_value numeric; v_max numeric; v_item_ids text[]; v_score_ids text[]:=''{}''; v_id text;\nbegin\n  if v_owner is null then raise exception using errcode=''42501'',message=''Authentication required''; end if;\n  if coalesce(length(p_mutation_id),0) not between 1 and 200 or coalesce(length(p_device_id),0) not between 1 and 200 or\n    jsonb_typeof(p_batch) is distinct from ''object'' or jsonb_typeof(p_batch->''cells'') is distinct from ''array'' or\n    jsonb_typeof(p_batch->''newItems'') is distinct from ''array'' then\n    raise exception using errcode=''22023'',message=''Invalid reviewed batch''; end if;\n  if jsonb_array_length(p_batch->''cells'') not between 1 and 15000 or jsonb_array_length(p_batch->''newItems'')>50 or\n    (select count(distinct x->>''studentId'') from jsonb_array_elements(p_batch->''cells'') x)>300 or\n    (select count(distinct x->>''itemId'') from jsonb_array_elements(p_batch->''cells'') x)>50 or\n    (select count(distinct (x->>''studentId'',x->>''itemId'')) from jsonb_array_elements(p_batch->''cells'') x)<>jsonb_array_length(p_batch->''cells'') or\n    (select count(distinct x->>''id'') from jsonb_array_elements(p_batch->''newItems'') x)<>jsonb_array_length(p_batch->''newItems'') then\n    raise exception using errcode=''22023'',message=''Duplicate or oversized reviewed batch''; end if;\n  -- Same ordering as existing lifecycle writes, then receipt and item locks.\n  perform rakeezx.lock_student_lifecycle(v_owner);\n  perform pg_advisory_xact_lock(hashtextextended(v_owner::text||'':score-domain-receipt:''||p_mutation_id,0));\n  v_envelope:=jsonb_build_object(''protocol'',''N90_REVIEWED_V1'',''deviceId'',p_device_id,''batch'',p_batch);\n  select * into v_saved from rakeezx.score_domain_receipts where owner_id=v_owner and mutation_id=p_mutation_id;\n  if found then\n    if v_saved.request_envelope is distinct from v_envelope then raise exception using errcode=''22023'',message=''Grade mutation ID reused''; end if;\n    return v_saved.result;\n  end if;\n  select * into v_teaching from rakeezx.teachings where owner_id=v_owner and id=p_batch->>''teachingId'' and deleted_at is null for update;\n  if v_teaching.id is null or v_teaching.revision is distinct from (p_batch->>''teachingRevision'')::bigint or\n    v_teaching.term_id is distinct from p_batch->>''termId'' or not exists (\n      select 1 from rakeezx.sections s join rakeezx.terms t on t.owner_id=s.owner_id and t.year_id=s.year_id\n      join rakeezx.years y on y.owner_id=s.owner_id and y.id=s.year_id\n      join rakeezx.subjects u on u.owner_id=s.owner_id and u.id=v_teaching.subject_id\n      where s.owner_id=v_owner and s.id=v_teaching.section_id and t.id=v_teaching.term_id and s.deleted_at is null\n        and t.deleted_at is null and y.deleted_at is null and u.deleted_at is null and s.status<>''archived'' and t.status=''active'' and y.status=''active'') then\n    raise exception using errcode=''PT409'',message=''Teaching or current term changed''; end if;\n  for v_new in select value from jsonb_array_elements(p_batch->''newItems'') order by value->>''id'' loop\n    v_max:=(v_new->>''max'')::numeric;\n    if coalesce(length(v_new->>''id''),0) not between 1 and 200 or coalesce(length(btrim(v_new->>''name'')),0) not between 1 and 50 or\n      v_max is null or v_max::text in (''NaN'',''Infinity'',''-Infinity'') or v_max<=0 or v_max>9999.99 or v_max<>round(v_max,2) or\n      not exists(select 1 from jsonb_array_elements(p_batch->''cells'') c where c->>''itemId''=v_new->>''id'') then\n      raise exception using errcode=''22023'',message=''Invalid explicit new manual item''; end if;\n    if exists(select 1 from rakeezx.items where owner_id=v_owner and id=v_new->>''id'') then\n      raise exception using errcode=''PT409'',message=''New item identity already exists''; end if;\n    insert into rakeezx.items(owner_id,id,teaching_id,name,max,"order",score_mode,auto,device_id)\n      values(v_owner,v_new->>''id'',v_teaching.id,btrim(v_new->>''name''),v_max,\n        coalesce((select max("order")+1 from rakeezx.items where owner_id=v_owner and teaching_id=v_teaching.id),0),''direct'',null,p_device_id);\n  end loop;\n  select array_agg(distinct x->>''itemId'' order by x->>''itemId'') into v_item_ids from jsonb_array_elements(p_batch->''cells'') x;\n  perform 1 from rakeezx.items where owner_id=v_owner and id=any(v_item_ids) order by id for update;\n  for v_cell in select value from jsonb_array_elements(p_batch->''cells'') order by value->>''itemId'',value->>''studentId'' loop\n    select * into v_item from rakeezx.items where owner_id=v_owner and id=v_cell->>''itemId'';\n    v_value:=(v_cell->>''value'')::numeric;\n    if v_item.id is null or v_item.deleted_at is not null or v_item.teaching_id<>v_teaching.id or v_item.score_mode<>''direct'' or v_item.auto is not null or\n      v_item.max is distinct from (v_cell->>''max'')::numeric or\n      (not exists(select 1 from jsonb_array_elements(p_batch->''newItems'') x where x->>''id''=v_item.id) and v_item.revision is distinct from (v_cell->>''itemRevision'')::bigint) or\n      v_value is null or v_value::text in (''NaN'',''Infinity'',''-Infinity'') or v_value<0 or v_value>v_item.max or v_value<>round(v_value,2) then\n      raise exception using errcode=''PT409'',message=''Item or grade changed or invalid''; end if;\n    if not exists(select 1 from rakeezx.students s join rakeezx.enrollments e on e.owner_id=s.owner_id and e.student_id=s.id\n      where s.owner_id=v_owner and s.id=v_cell->>''studentId'' and s.deleted_at is null and e.deleted_at is null and e.status=''active'' and e.section_id=v_teaching.section_id) then\n      raise exception using errcode=''42501'',message=''Student outside current enrollment''; end if;\n    select * into v_score from rakeezx.scores where owner_id=v_owner and student_id=v_cell->>''studentId'' and item_id=v_item.id for update;\n    if v_score.deleted_at is not null or v_score.id is distinct from v_cell->>''scoreId'' or\n      coalesce(v_score.revision,0) is distinct from (v_cell->>''scoreRevision'')::bigint or v_score.value is distinct from (v_cell->>''old'')::numeric then\n      raise exception using errcode=''PT409'',message=''Score changed since review''; end if;\n    if v_score.value is not null and v_score.value<>v_value and (p_batch->>''overwriteConfirmed'') is distinct from ''true'' then\n      raise exception using errcode=''22023'',message=''Explicit overwrite confirmation required''; end if;\n    if v_score.id is null then\n      v_id:=''sc:''||(v_cell->>''studentId'')||'':''||v_item.id;\n      insert into rakeezx.scores(owner_id,id,student_id,item_id,value,device_id)\n        values(v_owner,v_id,v_cell->>''studentId'',v_item.id,v_value,p_device_id);\n    else\n      v_id:=v_score.id;\n      update rakeezx.scores set value=v_value,device_id=p_device_id where owner_id=v_owner and id=v_id;\n    end if;\n    v_score_ids:=array_append(v_score_ids,v_id);\n  end loop;\n  v_result:=jsonb_build_object(''protocol'',''N90_REVIEWED_V1'',''mutationId'',p_mutation_id,''teachingId'',v_teaching.id,\n    ''items'',(select coalesce(jsonb_agg(to_jsonb(i) order by id),''[]'') from rakeezx.items i where owner_id=v_owner and id=any(v_item_ids)),\n    ''scores'',(select coalesce(jsonb_agg(to_jsonb(s) order by id),''[]'') from rakeezx.scores s where owner_id=v_owner and id=any(v_score_ids)),\n    ''score_subitems'',''[]''::jsonb,''score_subitem_completions'',''[]''::jsonb);\n  insert into rakeezx.score_domain_receipts(owner_id,mutation_id,request_envelope,result) values(v_owner,p_mutation_id,v_envelope,v_result);\n  return v_result;\nend; \nEND; ';
CREATE OR REPLACE FUNCTION rakeezx.apply_score_configuration_command(p_mutation_id text, p_device_id text, p_item_id text, p_expected_version bigint, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS E' DECLARE __n88_entry_lock_1031_8c4d text := pg_catalog.pg_advisory_xact_lock(1312307256,88)::text; BEGIN\n\ndeclare v_owner uuid:=auth.uid(); v_envelope jsonb; v_receipt rakeezx.score_domain_receipts%rowtype;\n  v_item rakeezx.items%rowtype; v_mode text; v_distribution text; v_max numeric(6,2);\n  v_definition jsonb; v_id text; v_name text; v_value numeric(6,2); v_order integer;\n  v_start date; v_due date; v_late numeric; v_old rakeezx.score_subitems%rowtype;\n  v_count integer; v_position integer:=0; v_total_cents bigint; v_each bigint;\n  v_ids text[]:=''{}''::text[]; v_student text; v_result jsonb; v_scores jsonb:=''[]''::jsonb;\nbegin\n  if v_owner is null then raise exception using errcode=''42501'',message=''Authentication required''; end if;\n  if coalesce(p_mutation_id,'''')='''' or char_length(p_mutation_id)>200 or\n     coalesce(p_device_id,'''')='''' or char_length(p_device_id)>200 or\n     coalesce(p_item_id,'''')='''' or p_expected_version is null or p_expected_version<1 or\n     p_payload is null or pg_catalog.jsonb_typeof(p_payload)<>''object'' or\n     pg_catalog.jsonb_typeof(p_payload->''subitems'')<>''array'' then\n    raise exception using errcode=''22023'',message=''Invalid score configuration envelope'';\n  end if;\n  v_envelope:=pg_catalog.jsonb_build_object(''deviceId'',p_device_id,''itemId'',p_item_id,\n    ''expectedVersion'',p_expected_version,''payload'',p_payload);\n  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(\n    v_owner::text||'':score-domain-receipt:''||p_mutation_id,0));\n  select * into v_receipt from rakeezx.score_domain_receipts\n    where owner_id=v_owner and mutation_id=p_mutation_id;\n  if found then\n    if v_receipt.request_envelope is distinct from v_envelope then\n      raise exception using errcode=''22023'',message=''Score mutation ID reused with different content'';\n    end if;\n    return v_receipt.result;\n  end if;\n  select * into v_item from rakeezx.items where owner_id=v_owner and id=p_item_id\n    and deleted_at is null for update;\n  if not found or v_item.distribution_version<>p_expected_version then\n    raise exception using errcode=''40001'',message=''Score configuration revision changed'';\n  end if;\n  v_mode:=p_payload->>''scoreMode'';\n  v_distribution:=p_payload->>''distributionMode'';\n  if (p_payload->>''max'')::numeric is distinct from\n      pg_catalog.round((p_payload->>''max'')::numeric,2) then\n    raise exception using errcode=''22023'',message=''Score maximum requires two-decimal precision'';\n  end if;\n  v_max:=(p_payload->>''max'')::numeric(6,2);\n  v_count:=pg_catalog.jsonb_array_length(p_payload->''subitems'');\n  if v_mode is null or v_mode not in (''direct'',''subitems'') or v_max is null or v_max<=0 or\n     (v_mode=''subitems'' and (v_distribution is null or v_distribution not in (''auto'',''manual'') or v_count<1 or v_count>200)) or\n     (v_mode=''direct'' and v_count<>0) then\n    raise exception using errcode=''22023'',message=''Invalid score configuration'';\n  end if;\n  if v_item.score_mode=''direct'' and v_mode=''subitems'' and exists(\n    select 1 from rakeezx.scores where owner_id=v_owner and item_id=p_item_id\n      and deleted_at is null and value is not null\n  ) and (p_payload->>''conversionStrategy'') is distinct from ''retain-as-manual'' then\n    raise exception using errcode=''22023'',message=''Direct scores require reviewed conversion'';\n  end if;\n  perform pg_catalog.set_config(''rakeezx.score_domain_write'',''on'',true);\n  if v_item.score_mode=''direct'' and v_mode=''subitems'' then\n    update rakeezx.scores set manual_value=value,derived_value=0\n      where owner_id=v_owner and item_id=p_item_id and deleted_at is null;\n  end if;\n  update rakeezx.items set max=v_max,score_mode=v_mode,\n    distribution_mode=case when v_mode=''subitems'' then v_distribution else null end,\n    portability_group_id=case when v_mode=''subitems'' then null else portability_group_id end,\n    distribution_version=p_expected_version+1,device_id=p_device_id\n    where owner_id=v_owner and id=p_item_id returning * into v_item;\n  if v_mode=''direct'' then\n    update rakeezx.scores set manual_value=null,derived_value=null,device_id=p_device_id\n      where owner_id=v_owner and item_id=p_item_id and deleted_at is null;\n  else\n    v_total_cents:=pg_catalog.round(v_max*100)::bigint;\n    v_each:=v_total_cents/v_count;\n    for v_definition in select value from pg_catalog.jsonb_array_elements(p_payload->''subitems'') loop\n      v_position:=v_position+1;\n      v_id:=v_definition->>''id''; v_name:=v_definition->>''name'';\n      if coalesce(v_id,'''')='''' or char_length(v_id)>240 or coalesce(v_name,'''')='''' or\n         v_id=any(v_ids) or pg_catalog.jsonb_typeof(v_definition)<>''object'' then\n        raise exception using errcode=''22023'',message=''Invalid or duplicate subitem identity'';\n      end if;\n      v_ids:=pg_catalog.array_append(v_ids,v_id);\n      v_order:=v_position-1;\n      if v_distribution=''auto'' then\n        v_value:=(case when v_position=v_count then v_total_cents-v_each*(v_count-1)\n          else v_each end)::numeric/100;\n      else\n        if (v_definition->>''value'')::numeric is distinct from\n            pg_catalog.round((v_definition->>''value'')::numeric,2) then\n          raise exception using errcode=''22023'',message=''Subitem value requires two-decimal precision'';\n        end if;\n        v_value:=(v_definition->>''value'')::numeric(6,2);\n        if v_value is null or v_value<0 then\n          raise exception using errcode=''22023'',message=''Invalid manual subitem value'';\n        end if;\n      end if;\n      if exists(select 1 from rakeezx.score_subitems where owner_id=v_owner and id=v_id\n        and (item_id<>p_item_id or deleted_at is not null)) then\n        raise exception using errcode=''22023'',message=''Subitem identity is unavailable'';\n      end if;\n      select * into v_old from rakeezx.score_subitems where owner_id=v_owner and id=v_id;\n      v_start:=case when v_definition ? ''startDate'' then nullif(v_definition->>''startDate'','''')::date else v_old.start_date end;\n      v_due:=case when v_definition ? ''dueDate'' then nullif(v_definition->>''dueDate'','''')::date else v_old.due_date end;\n      v_late:=case when v_definition ? ''latePoints'' then nullif(v_definition->>''latePoints'','''')::numeric else v_old.late_points end;\n      insert into rakeezx.score_subitems(owner_id,id,item_id,name,value,"order",distribution_version,start_date,due_date,late_points,device_id)\n        values(v_owner,v_id,p_item_id,v_name,v_value,v_order,p_expected_version+1,v_start,v_due,v_late,p_device_id)\n        on conflict(owner_id,id) do update set name=excluded.name,value=excluded.value,\n          "order"=excluded."order",distribution_version=excluded.distribution_version,\n          start_date=excluded.start_date,due_date=excluded.due_date,late_points=excluded.late_points,device_id=excluded.device_id;\n    end loop;\n    update rakeezx.score_subitems set deleted_at=pg_catalog.clock_timestamp(),device_id=p_device_id\n      where owner_id=v_owner and item_id=p_item_id and deleted_at is null and not(id=any(v_ids));\n    for v_student in\n      select distinct student_id from rakeezx.scores\n        where owner_id=v_owner and item_id=p_item_id and deleted_at is null\n      union\n      select distinct c.student_id from rakeezx.score_subitem_completions c\n        join rakeezx.score_subitems d on d.owner_id=c.owner_id and d.id=c.subitem_id\n        where c.owner_id=v_owner and d.item_id=p_item_id and c.checked and c.deleted_at is null\n    loop\n      v_scores:=v_scores||pg_catalog.jsonb_build_array(\n        rakeezx.recompute_subitem_score(v_owner,p_item_id,v_student,p_device_id));\n    end loop;\n  end if;\n  v_result:=pg_catalog.jsonb_build_object(''mutationId'',p_mutation_id,\n    ''item'',pg_catalog.to_jsonb(v_item),''scores'',v_scores,\n    ''subitems'',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(d) order by d."order",d.id),''[]''::jsonb)\n      from rakeezx.score_subitems d where d.owner_id=v_owner and d.item_id=p_item_id));\n  insert into rakeezx.score_domain_receipts(owner_id,mutation_id,request_envelope,result)\n    values(v_owner,p_mutation_id,v_envelope,v_result);\n  return v_result;\nend; \nEND; ';
CREATE OR REPLACE FUNCTION rakeezx.apply_score_distribution_copy_command(p_mutation_id text, p_device_id text, p_source_item_id text, p_source_revision bigint, p_target_teaching_id text, p_new_item_id text, p_subitem_ids jsonb, p_conflict_choice text)
 RETURNS jsonb
 LANGUAGE plpgsql
